#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long target;
    cin >> n >> target;
    vector<vector<long long>> cars(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> cars[i][j];
        }
    }

    sort(cars.begin(), cars.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[0] > y[0]; });
    long long fleets = 0, slowDist = 0, slowSpeed = 1;
    for (int i = 0; i < n; i++) {
        long long dist = target - cars[i][0], speed = cars[i][1];
        if (dist * slowSpeed > slowDist * speed) {
            fleets++;
            slowDist = dist;
            slowSpeed = speed;
        }
    }
    cout << fleets << "\n";

    return 0;
}

