import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long target = Long.parseLong(next());
        long[][] cars = new long[(int) n][2];
        for (int i = 0; i < cars.length; i++) {
            for (int j = 0; j < cars[i].length; j++) {
                cars[i][j] = Long.parseLong(next());
            }
        }

        Arrays.sort(cars, (x, y) -> Long.compare(y[0], x[0]));
        long fleets = 0, slowDist = 0, slowSpeed = 1;
        for (int i = 0; i < n; i++) {
            long dist = target - cars[i][0], speed = cars[i][1];
            if (dist * slowSpeed > slowDist * speed) {
                fleets++;
                slowDist = dist;
                slowSpeed = speed;
            }
        }
        System.out.println(fleets);
    }
}
